package com.acme.core.common.core;

import java.util.List;

/**
 * Page result contract (generated by engineering-platform 0.1.0).
 * Persistence-framework neutral: no IPage / Page / Wrapper exposure.
 */
public record PageResult<T>(List<T> items, long total, int page, int size) {

    public static <T> PageResult<T> of(List<T> items, long total, int page, int size) {
        return new PageResult<>(items, total, page, size);
    }

    public static <T> PageResult<T> empty(PageQuery query) {
        return new PageResult<>(List.of(), 0, query.page(), query.size());
    }
}
